  1	# Agent Hub Web 生产环境 Nginx 配置（完整 nginx.conf）
  2	#
  3	# 用法：
  4	#   1. 备份原 /etc/nginx/nginx.conf；
  5	#   2. 按实际环境修改 upstream 地址与 root；
  6	#   3. 用本文件替换 /etc/nginx/nginx.conf；
  7	#   4. nginx -t && nginx -s reload。
  8	#
  9	# 注意：本文件是完整配置（含 events/http/server），不是 conf.d 片段。
 10	# 若部署环境只允许投放 conf.d 片段，请把 server { ... } 拆出，并确保
 11	# 主配置的 http 块内存在同名 upstream agent-hub-backend。
 12	
 13	worker_processes auto;
 14	pid /var/run/nginx.pid;
 15	error_log /var/log/nginx/error.log warn;
 16	
 17	events {
 18	    worker_connections 1024;
 19	    multi_accept on;
 20	}
 21	
 22	http {
 23	    include /etc/nginx/mime.types;
 24	    default_type application/octet-stream;
 25	
 26	    log_format main '$remote_addr - $remote_user [$time_local] "$request" '
 27	                    '$status $body_bytes_sent "$http_referer" '
 28	                    '"$http_user_agent" "$http_x_forwarded_for" '
 29	                    'rt=$request_time urt=$upstream_response_time';
 30	    access_log /var/log/nginx/access.log main;
 31	
 32	    sendfile on;
 33	    tcp_nopush on;
 34	    keepalive_timeout 65;
 35	    server_tokens off;
 36	
 37	    # 普通文本资源启用压缩；SSE 的 location 内单独 gzip off。
 38	    gzip on;
 39	    gzip_vary on;
 40	    gzip_min_length 1024;
 41	    gzip_types
 42	        text/plain
 43	        text/css
 44	        text/javascript
 45	        application/javascript
 46	        application/json
 47	        application/xml
 48	        image/svg+xml;
 49	
 50	    # 后端地址：容器编排中可改为服务名（如 agent-hub-backend:8000）。
 51	    # keepalive 复用少量后端连接，降低普通 JSON 请求的握手开销。
 52	    upstream agent-hub-backend {
 53	        server 127.0.0.1:8000;
 54	        keepalive 32;
 55	    }
 56	
 57	    server {
 58	        listen 80;
 59	        server_name _;
 60	
 61	        root /usr/share/nginx/html;
 62	        index index.html;
 63	
 64	        # SPA fallback：真实文件优先；刷新前端路由时回落到 index.html。
 65	        location / {
 66	            try_files $uri $uri/ /index.html;
 67	        }
 68	
 69	        # 带内容哈希的构建产物：一年强缓存 + immutable，减少重复下载。
 70	        # 文件名随内容变化，因此可以安全地使用长缓存。
 71	        location /assets/ {
 72	            expires 1y;
 73	            add_header Cache-Control "public, immutable";
 74	            access_log off;
 75	            # 不存在的资源直接 404，避免 SPA fallback 把 index.html
 76	            # 当成 JS/CSS 返回（会导致浏览器报 MIME 类型错误）。
 77	            try_files $uri =404;
 78	        }
 79	
 80	        # 入口 HTML 不能长缓存，否则用户会一直拿到旧版本的 assets 引用。
 81	        location = /index.html {
 82	            add_header Cache-Control "no-cache";
 83	        }
 84	
 85	        # 普通 API 反代。聊天 SSE 有独立的精确 location（见下），
 86	        # 不会受到这里 60s 读超时与默认缓冲的影响。
 87	        location /api/ {
 88	            proxy_pass http://agent-hub-backend;
 89	            proxy_http_version 1.1;
 90	            proxy_set_header Host $host;
 91	            proxy_set_header X-Real-IP $remote_addr;
 92	            proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
 93	            proxy_set_header X-Forwarded-Proto $scheme;
 94	            proxy_set_header X-Request-ID $request_id;
 95	            proxy_set_header Connection "";
 96	            proxy_connect_timeout 10s;
 97	            proxy_read_timeout 60s;
 98	            proxy_send_timeout 60s;
 99	        }
100	
101	        # 聊天流专用 SSE 端点（POST + text/event-stream）。
102	        # 精确匹配（=）优先于前缀匹配 /api/，因此这里的长连接参数是最终生效值。
103	        location = /api/v1/chat/stream {
104	            proxy_pass http://agent-hub-backend;
105	
106	            # 使用 HTTP/1.1 与后端通信。HTTP/1.0 默认短连接、无 chunked，
107	            # 不适合长时间流式响应。
108	            proxy_http_version 1.1;
109	
110	            proxy_set_header Host $host;
111	            proxy_set_header X-Real-IP $remote_addr;
